package dev.slopclient.cosmetics;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import com.mojang.math.Axis;
import java.util.ArrayList;
import java.util.List;
import net.minecraft.resources.Identifier;
import net.minecraft.util.LightCoordsUtil;

/**
 * Pets from {@code cosmetics/extras.json} (generated by tools/pets/build.py): textured
 * boxes in Minecraft's box UV layout, grouped into parts that animate around a pivot.
 * The launcher's preview (lib/extras.ts) reads the same data and animates it the same way.
 */
public final class Pets {
	public enum Tier { SHOULDER, FLYING, WALKING }

	record Box(float x, float y, float z, int w, int h, int d, int u, int v, String color, boolean glow, float sw, float sh, float sd) {
	}

	record Part(float px, float py, float pz, String anim, boolean glow, List<Box> boxes) {
	}

	public record Pet(String id, String name, Tier tier, boolean minime, boolean spin, float scale, Identifier texture, int texW, int texH, List<Part> parts) {
	}

	private Pets() {
	}

	static Pet read(JsonObject o) {
		String id = o.get("id").getAsString();
		Tier tier = switch (o.has("tier") ? o.get("tier").getAsString() : "shoulder") {
			case "flying" -> Tier.FLYING;
			case "walking" -> Tier.WALKING;
			default -> Tier.SHOULDER;
		};
		boolean minime = o.has("special") && o.get("special").getAsString().equals("minime");
		Identifier texture = o.has("texture") ? Identifier.fromNamespaceAndPath(Cosmetics.NS, "textures/pets/" + o.get("texture").getAsString()) : Extras.TEXTURE;
		int texW = 64, texH = 64;
		if (o.has("textureSize")) {
			texW = o.getAsJsonArray("textureSize").get(0).getAsInt();
			texH = o.getAsJsonArray("textureSize").get(1).getAsInt();
		}
		List<Part> parts = new ArrayList<>();
		if (o.has("parts")) {
			for (JsonElement pe : o.getAsJsonArray("parts")) {
				JsonObject p = pe.getAsJsonObject();
				JsonArray pivot = p.getAsJsonArray("pivot");
				List<Box> boxes = new ArrayList<>();
				for (JsonElement be : p.getAsJsonArray("boxes")) {
					JsonObject b = be.getAsJsonObject();
					JsonArray from = b.getAsJsonArray("from"), size = b.getAsJsonArray("size");
					JsonArray uv = b.has("uv") ? b.getAsJsonArray("uv") : null;
					boxes.add(new Box(from.get(0).getAsFloat(), from.get(1).getAsFloat(), from.get(2).getAsFloat(),
						(int) Math.ceil(size.get(0).getAsFloat()), (int) Math.ceil(size.get(1).getAsFloat()), (int) Math.ceil(size.get(2).getAsFloat()),
						uv == null ? 0 : uv.get(0).getAsInt(), uv == null ? 0 : uv.get(1).getAsInt(),
						b.has("color") ? b.get("color").getAsString() : null, b.has("glow") && b.get("glow").getAsBoolean(),
						size.get(0).getAsFloat(), size.get(1).getAsFloat(), size.get(2).getAsFloat()));
				}
				parts.add(new Part(pivot.get(0).getAsFloat(), pivot.get(1).getAsFloat(), pivot.get(2).getAsFloat(),
					p.has("anim") ? p.get("anim").getAsString() : null, p.has("glow") && p.get("glow").getAsBoolean(), boxes));
			}
		}
		float scale = o.has("scale") ? o.get("scale").getAsFloat() : 1;
		return new Pet(id, o.get("name").getAsString(), tier, minime, o.has("spin") && o.get("spin").getAsBoolean(), scale, texture, texW, texH, parts);
	}

	// ---------- animation (same as animate() in the launcher) ----------

	/** rx, ry, rz in radians around the model axes, dy in pixels, sy as y scale. */
	record PartPose(float rx, float ry, float rz, float dy, float sy) {
	}

	static PartPose animate(String anim, float t, float walk, float speed) {
		float swing = (float) Math.sin(walk * 0.6662) * 0.9f * speed;
		if (anim == null) return new PartPose(0, 0, 0, 0, 1);
		return switch (anim) {
			case "breathe" -> new PartPose(0, 0, 0, 0, 1 + (float) Math.sin(t * 0.1) * 0.025f);
			case "head" -> new PartPose((float) Math.sin(t * 0.07) * 0.06f, (float) Math.sin(t * 0.031) * 0.15f, 0, 0, 1);
			case "tail" -> new PartPose(0, (float) Math.sin(t * 0.12) * 0.35f, 0, 0, 1);
			case "wag" -> new PartPose(0, (float) Math.sin(t * 0.55) * 0.45f, 0, 0, 1);
			case "wingL" -> new PartPose(0, 0, (float) Math.sin(t * 0.45) * 0.6f, 0, 1);
			case "wingR" -> new PartPose(0, 0, -(float) Math.sin(t * 0.45) * 0.6f, 0, 1);
			case "buzzL" -> new PartPose(0, 0, (float) Math.sin(t * 2.2) * 0.45f, 0, 1);
			case "buzzR" -> new PartPose(0, 0, -(float) Math.sin(t * 2.2) * 0.45f, 0, 1);
			case "flipperL" -> new PartPose(0, 0, -0.12f - (float) Math.sin(t * 0.18) * 0.12f, 0, 1);
			case "flipperR" -> new PartPose(0, 0, 0.12f + (float) Math.sin(t * 0.18) * 0.12f, 0, 1);
			case "legA" -> new PartPose(swing, 0, 0, 0, 1);
			case "legB" -> new PartPose(-swing, 0, 0, 0, 1);
			case "bob" -> new PartPose(0, 0, 0, (float) Math.sin(t * 0.1) * 0.6f, 1);
			case "squish" -> new PartPose(0, 0, 0, 0, 1 + (float) Math.sin(t * 0.15) * 0.07f);
			default -> new PartPose(0, 0, 0, 0, 1);
		};
	}

	// ---------- geometry ----------

	/**
	 * Draws the pet; the pose is in blocks with y down (model space), the pet in pixels.
	 * Textured boxes go to `out`, coloured ones to `plain` (white texture).
	 */
	static void emit(Pet pet, PoseStack pose, VertexConsumer out, int light, int overlay, float t, float walk, float speed) {
		pose.pushPose();
		pose.scale(pet.scale / 16f, pet.scale / 16f, pet.scale / 16f);
		if (pet.spin) {
			pose.rotateDegrees(Axis.YP, t * 2.4f);
			pose.rotateDegrees(Axis.XP, t * 1.3f);
		}
		for (Part part : pet.parts) {
			PartPose p = animate(part.anim, t, walk, speed);
			pose.pushPose();
			pose.translate(part.px, part.py + p.dy, part.pz);
			if (p.rz != 0) pose.rotate(Axis.ZP, p.rz);
			if (p.ry != 0) pose.rotate(Axis.YP, p.ry);
			if (p.rx != 0) pose.rotate(Axis.XP, p.rx);
			if (p.sy != 1) pose.scale(1, p.sy, 1);
			pose.translate(-part.px, -part.py, -part.pz);
			PoseStack.Pose last = pose.last();
			for (Box b : part.boxes) {
				int l = part.glow || b.glow ? LightCoordsUtil.FULL_BRIGHT : light;
				int color = b.color == null ? -1 : 0xFF000000 | rgb(b.color, t / 60.0);
				// Coloured boxes sample the texture's corner, which the generator leaves
				// empty; they use the plain white texture through a separate pass instead.
				if (b.color != null) continue;
				box(last, out, b, pet.texW, pet.texH, l, overlay, color);
			}
			pose.popPose();
		}
		pose.popPose();
	}

	/** Second pass: the plain coloured boxes (chroma cube, glowing eyes) with the white texture. */
	static void emitColored(Pet pet, PoseStack pose, VertexConsumer out, int light, int overlay, float t, float walk, float speed) {
		pose.pushPose();
		pose.scale(pet.scale / 16f, pet.scale / 16f, pet.scale / 16f);
		if (pet.spin) {
			pose.rotateDegrees(Axis.YP, t * 2.4f);
			pose.rotateDegrees(Axis.XP, t * 1.3f);
		}
		for (Part part : pet.parts) {
			PartPose p = animate(part.anim, t, walk, speed);
			pose.pushPose();
			pose.translate(part.px, part.py + p.dy, part.pz);
			if (p.rz != 0) pose.rotate(Axis.ZP, p.rz);
			if (p.ry != 0) pose.rotate(Axis.YP, p.ry);
			if (p.rx != 0) pose.rotate(Axis.XP, p.rx);
			if (p.sy != 1) pose.scale(1, p.sy, 1);
			pose.translate(-part.px, -part.py, -part.pz);
			PoseStack.Pose last = pose.last();
			for (Box b : part.boxes) {
				if (b.color == null) continue;
				int l = part.glow || b.glow ? LightCoordsUtil.FULL_BRIGHT : light;
				Box sized = new Box(b.x, b.y, b.z, 0, 0, 0, 0, 0, b.color, b.glow, b.sw, b.sh, b.sd);
				coloredBox(last, out, sized, l, overlay, 0xFF000000 | rgb(b.color, t / 60.0));
			}
			pose.popPose();
		}
		pose.popPose();
	}

	static boolean hasColored(Pet pet) {
		for (Part p : pet.parts) for (Box b : p.boxes) if (b.color != null) return true;
		return false;
	}

	private static int rgb(String spec, double phase) {
		return switch (spec) {
			case "accent" -> Cosmetics.settings().accent() & 0xFFFFFF;
			case "accent2" -> Cosmetics.settings().accent2() & 0xFFFFFF;
			case "chroma" -> Cosmetics.settings().chroma(phase) & 0xFFFFFF;
			default -> {
				try {
					yield Integer.parseInt(spec.substring(1), 16);
				} catch (RuntimeException e) {
					yield 0xFF00FF;
				}
			}
		};
	}

	/** Faces in the layout of tools/pets/build.py: rect (u, v, w, h) and corners for (u0,v0) (u1,v0) (u1,v1) (u0,v1). */
	private static void box(PoseStack.Pose pose, VertexConsumer out, Box b, int tw, int th, int light, int overlay, int color) {
		float x1 = b.x, y1 = b.y, z1 = b.z, x2 = b.x + b.w, y2 = b.y + b.h, z2 = b.z + b.d;
		int u = b.u, v = b.v, w = b.w, h = b.h, d = b.d;
		face(pose, out, tw, th, u + d, v, w, d, light, overlay, color, 0, -1, 0, x1, y1, z1, x2, y1, z1, x2, y1, z2, x1, y1, z2);
		face(pose, out, tw, th, u + d + w, v, w, d, light, overlay, color, 0, 1, 0, x1, y2, z2, x2, y2, z2, x2, y2, z1, x1, y2, z1);
		face(pose, out, tw, th, u, v + d, d, h, light, overlay, color, -1, 0, 0, x1, y1, z1, x1, y1, z2, x1, y2, z2, x1, y2, z1);
		face(pose, out, tw, th, u + d, v + d, w, h, light, overlay, color, 0, 0, -1, x1, y1, z1, x2, y1, z1, x2, y2, z1, x1, y2, z1);
		face(pose, out, tw, th, u + d + w, v + d, d, h, light, overlay, color, 1, 0, 0, x2, y1, z2, x2, y1, z1, x2, y2, z1, x2, y2, z2);
		face(pose, out, tw, th, u + 2 * d + w, v + d, w, h, light, overlay, color, 0, 0, 1, x2, y1, z2, x1, y1, z2, x1, y2, z2, x2, y2, z2);
	}

	private static void coloredBox(PoseStack.Pose pose, VertexConsumer out, Box b, int light, int overlay, int color) {
		float x1 = b.x, y1 = b.y, z1 = b.z, x2 = b.x + b.sw, y2 = b.y + b.sh, z2 = b.z + b.sd;
		face(pose, out, 1, 1, 0, 0, 1, 1, light, overlay, color, 0, -1, 0, x1, y1, z1, x2, y1, z1, x2, y1, z2, x1, y1, z2);
		face(pose, out, 1, 1, 0, 0, 1, 1, light, overlay, color, 0, 1, 0, x1, y2, z2, x2, y2, z2, x2, y2, z1, x1, y2, z1);
		face(pose, out, 1, 1, 0, 0, 1, 1, light, overlay, color, -1, 0, 0, x1, y1, z1, x1, y1, z2, x1, y2, z2, x1, y2, z1);
		face(pose, out, 1, 1, 0, 0, 1, 1, light, overlay, color, 0, 0, -1, x1, y1, z1, x2, y1, z1, x2, y2, z1, x1, y2, z1);
		face(pose, out, 1, 1, 0, 0, 1, 1, light, overlay, color, 1, 0, 0, x2, y1, z2, x2, y1, z1, x2, y2, z1, x2, y2, z2);
		face(pose, out, 1, 1, 0, 0, 1, 1, light, overlay, color, 0, 0, 1, x2, y1, z2, x1, y1, z2, x1, y2, z2, x2, y2, z2);
	}

	private static void face(PoseStack.Pose pose, VertexConsumer out, int tw, int th, int ru, int rv, int rw, int rh, int light, int overlay, int color,
		float nx, float ny, float nz, float... c) {
		float u0 = ru / (float) tw, v0 = rv / (float) th, u1 = (ru + rw) / (float) tw, v1 = (rv + rh) / (float) th;
		float[][] uv = {{u0, v0}, {u1, v0}, {u1, v1}, {u0, v1}};
		for (int i = 0; i < 4; i++) {
			out.addVertex(pose, c[i * 3], c[i * 3 + 1], c[i * 3 + 2])
				.setColor(color)
				.setUv(uv[i][0], uv[i][1])
				.setOverlay(overlay)
				.setLight(light)
				.setNormal(pose, nx, ny, nz);
		}
	}
}
